/* Original EAHS model extensions. Quantitative outputs are educational models with explicit assumptions. */
const ExtraTools={},ExtraRenderers={},ExtraMath={};
const N=(key,label,value,min,max,step=1,help='')=>({key,label,value,min,max,step,type:'number',help});
const S=(key,label,value,options,help='')=>({key,label,value,options,type:'select',help});
const T=(key,label,value,help='',area=false)=>({key,label,value,type:area?'textarea':'text',help});
function add(unit,id,title,topics,sub,fields,equation,assumptions,prompt,draw){ExtraTools[id]={unit,title,topics,tag:`UNIT ${unit} · TOPICS ${topics}`,sub,fields,equation,assumptions,prompt,source:'https://apcentral.collegeboard.org/media/pdf/ap-biology-course-and-exam-description.pdf'};ExtraRenderers[id]=draw;}
const mean=a=>a.reduce((s,x)=>s+x,0)/a.length;
function seq(raw){const x=raw.toUpperCase().replace(/\s/g,'');if(!/^[ACGT]+$/.test(x)||x.length>600)throw Error('Enter 1–600 DNA bases using A, C, G and T.');return x;}
const complement=x=>x.replace(/[ACGT]/g,c=>({A:'T',C:'G',G:'C',T:'A'}[c])),revcomp=x=>complement(x).split('').reverse().join('');
const codons={};'FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'.split('').forEach((aa,i)=>{const bases='UCAG';codons[bases[Math.floor(i/16)]+bases[Math.floor(i/4)%4]+bases[i%4]]=aa});
function translate(rna,frame=0){let protein='',triplets=[];for(let i=frame;i+2<rna.length;i+=3){let c=rna.slice(i,i+3),aa=codons[c];triplets.push([c,aa]);if(aa==='*')break;protein+=aa;}return{protein,triplets};}
function seeded(seed){let n=(seed>>>0)||1;return()=>{n=(1664525*n+1013904223)>>>0;return n/4294967296;};}
function sampleBinomial(n,p,rng){let count=0;for(let i=0;i<n;i++)if(rng()<p)count++;return count;}
function choose(n,k){let v=1;for(let i=1;i<=k;i++)v=v*(n-i+1)/i;return v;}
function normal(x,m,sd){return Math.exp(-.5*((x-m)/sd)**2)/(sd*Math.sqrt(2*Math.PI));}
function grid(points,labels){let body='';points.forEach(([label,value],i)=>{let x=80+(i%3)*250,y=105+Math.floor(i/3)*125;body+=`<rect x="${x}" y="${y}" width="220" height="94" rx="8" fill="#eef3fa" stroke="#d3deeb"/>${text(x+110,y+29,label,13,'text-anchor="middle"')}${text(x+110,y+63,value,21,'text-anchor="middle"')}`});if(labels)body+=text(410,440,labels,12,'text-anchor="middle"');return svg(body,475);}
function pathDiagram(nodes,active=nodes.map(()=>true),caption=''){let body='';const width=150,cols=4;nodes.forEach((label,i)=>{let row=Math.floor(i/cols),col=row%2?cols-1-i%cols:i%cols,x=70+col*180,y=100+row*115;let fill=active[i]?'#e7efff':'#fff0f1';body+=`<rect x="${x}" y="${y}" width="${width}" height="65" rx="8" fill="${fill}" stroke="${active[i]?'#234bb0':'#a03246'}"/>`;String(label).split('|').forEach((t,j)=>body+=text(x+75,y+27+j*19,t,13,'text-anchor="middle"'));if(i<nodes.length-1){let nx,ny;if(i%cols===cols-1){nx=x+75;ny=y+115;body+=line(x+75,y+65,nx,ny,'#63748b');}else{const dir=row%2?-1:1;body+=line(dir===1?x+width:x,y+32,dir===1?x+180:x-30,y+32,'#63748b');}}});body+=text(410,100+Math.ceil(nodes.length/4)*115+20,caption,12,'text-anchor="middle"');return svg(body,Math.max(340,160+Math.ceil(nodes.length/4)*115));}
function sequenceFigure(lines,caption=''){let body='';lines.forEach(([label,bases],i)=>{body+=text(55,100+i*105,label,14);let chunks=String(bases).match(/.{1,55}/g)||[''];chunks.slice(0,2).forEach((t,j)=>body+=text(55,132+i*105+j*26,t,17,'font-family="monospace"'));});body+=text(55,110+lines.length*105,caption,12);return svg(body,160+lines.length*105);}
function branchingDiagram(nodes,edges,caption){let body='<defs><marker id="branch-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#63748b"/></marker></defs>';edges.forEach(points=>body+=`<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#63748b" stroke-width="1.5" marker-end="url(#branch-arrow)"/>`);nodes.forEach(([x,y,label,active])=>{body+=`<rect x="${x}" y="${y}" width="150" height="65" rx="8" fill="${active?'#e7efff':'#fff0f1'}" stroke="${active?'#234bb0':'#a03246'}"/>`;label.split('|').forEach((t,j)=>body+=text(x+75,y+27+j*19,t,13,'text-anchor="middle"'));});body+=text(410,470,caption,12,'text-anchor="middle"');return svg(body,495);}
function output(figure,result,rows){if(rows)data=rows;return{figure,result};}
function linearPlot(rows,names,xlabel,ylabel){return chart(names.map((name,i)=>({name,color:colors()[i%3],values:rows.map(r=>[r[0],r[i+1]])})),xlabel,ylabel);}
function integrate(v,derivative,time,steps=5000){let h=time/steps,rows=[[0,...v]];for(let i=1;i<=steps;i++){let a=derivative(v),b=derivative(v.map((x,j)=>x+h*a[j]/2)),c=derivative(v.map((x,j)=>x+h*b[j]/2)),d=derivative(v.map((x,j)=>x+h*c[j]));v=v.map((x,j)=>x+h*(a[j]+2*b[j]+2*c[j]+d[j])/6);if(v.some(x=>!Number.isFinite(x)||x<-1e-6||x>1e10))throw Error('These parameters exceed this model’s valid numerical range. Reduce rates or time.');v=v.map(x=>Math.max(0,x));if(i%10===0)rows.push([i*h,...v]);}return rows;}
Object.assign(ExtraMath,{seq,complement,revcomp,translate,seeded,sampleBinomial,choose,integrate});
