add(1,'water-bonds','Water & hydrogen bonding','1.1','Explore molecular polarity and distinguish covalent bonds from intermolecular attractions.',[S('arrangement','Arrangement','liquid',[['liquid','Liquid water'],['ice','Open ice lattice schematic']]),N('temperature','Temperature (°C)',25,0,100),S('bond','Highlight','hydrogen',[['hydrogen','Hydrogen bonds'],['covalent','Covalent O–H bonds']])],'Hydrogen bonds connect partial charges on different water molecules.','Schematic molecular arrangements, not a molecular-dynamics simulation. Temperature changes a qualitative motion indicator, not a calculated bond lifetime. Ice geometry is illustrative rather than crystallographically exact.','Explain how an open hydrogen-bonded lattice can make ice less dense than liquid water.',s=>{let out='';let pts=s.arrangement==='ice'?[[230,130],[460,130],[345,300],[575,300]]:[[260,130],[400,160],[330,290],[530,260]];pts.forEach(([x,y])=>{out+=`<circle cx="${x}" cy="${y}" r="22" fill="#234bb0"/><circle cx="${x-45}" cy="${y+30}" r="13" fill="#bf9b50"/><circle cx="${x+45}" cy="${y+30}" r="13" fill="#bf9b50"/>${line(x-18,y+10,x-35,y+24,s.bond==='covalent'?'#a03246':'#6a7a8f')}${line(x+18,y+10,x+35,y+24,s.bond==='covalent'?'#a03246':'#6a7a8f')}${text(x,y+5,'δ−',12,'fill="white" text-anchor="middle"')}${text(x-45,y+57,'δ+',12,'text-anchor="middle"')}`});if(s.bond==='hydrogen')for(let i=0;i<pts.length-1;i++)out+=line(pts[i][0]+45,pts[i][1]+30,pts[i+1][0]-22,pts[i+1][1],'#a03246','stroke-dasharray="5 4"');out+=text(410,410,s.arrangement==='ice'?'Open lattice schematic':'Dynamic liquid arrangement schematic',16,'text-anchor="middle"');return output(svg(out),metrics([[s.temperature+' °C','Selected temperature'],[s.temperature<25?'Lower':s.temperature>25?'Higher':'Reference','Molecular kinetic energy relative to 25 °C']]),[['Arrangement','Temperature','Highlight'],[s.arrangement,s.temperature,s.bond]])});
add(1,'atoms','Element & atom accounting','1.2','Count atoms in biological molecules and track matter through balanced reactions.',[T('formula','Molecular formula','C6H12O6','Supported elements: C, H, O, N, P, S. No parentheses.'),N('molecules','Number of molecules',6,1,1000)],'Atoms are conserved in chemical reactions.','Formula parsing counts atoms; it does not infer molecular structure, bond energy, or reaction feasibility.','Why can a carbon atom be recycled while usable energy is progressively dissipated?',s=>{if(!/^(?:[CHONPS]\d*)+$/.test(s.formula))throw Error('Use a simple formula such as C6H12O6 or C5H5N5.');let counts={};for(const m of s.formula.matchAll(/([CHONPS])(\d*)/g)){let n=+(m[2]||1);if(n<1||n>1000)throw Error('Atom subscripts must be 1–1000.');counts[m[1]]=(counts[m[1]]||0)+n*s.molecules;}return output(grid(Object.entries(counts).map(([a,n])=>[a,n+' atoms'])),table(['Element','Atoms per molecule','Total atoms'],Object.entries(counts).map(([a,n])=>[a,n/s.molecules,n])),[['Element','Atoms'],...Object.entries(counts)])});
add(1,'polymers','Polymer assembly & hydrolysis','1.3','Account for monomers, bonds, and water in a linear chain.',[N('monomers','Monomers in chain',8,2,20),N('broken','Bonds hydrolyzed',2,0,19),S('reaction','Reaction','hydrolysis',[['hydrolysis','Hydrolysis'],['assembly','Dehydration synthesis']])],'A linear chain of n monomers has n − 1 links.','Each displayed link represents one condensation/hydrolysis event. This is an accounting model, not a universal cellular synthesis mechanism; nucleic-acid synthesis, for example, uses activated nucleotides.','Explain why forming a chain of 8 monomers involves 7 links.',s=>{if(s.broken>=s.monomers)throw Error('Broken bonds must be fewer than monomers.');let out='';for(let i=0;i<s.monomers;i++){let x=60+i*700/(s.monomers-1);out+=`<circle cx="${x}" cy="210" r="15" fill="#234bb0"/>`;if(i<s.monomers-1)out+=line(x+15,210,x+700/(s.monomers-1)-15,210,s.reaction==='hydrolysis'&&i<s.broken?'#a03246':'#65778e',s.reaction==='hydrolysis'&&i<s.broken?'stroke-dasharray="3 5"':'');}let n=s.reaction==='hydrolysis'?s.broken:s.monomers-1;return output(svg(out+text(410,310,`${n} water molecules ${s.reaction==='hydrolysis'?'consumed':'produced'}`,18,'text-anchor="middle"'),400),metrics([[s.monomers-1,'Original links'],[s.reaction==='hydrolysis'?s.broken+1:1,'Resulting chains'],[n,'Water molecules accounted for']]))});
add(1,'carbohydrates','Carbohydrate structure','1.4','Compare branching and linkage orientation in storage and structural polysaccharides.',[S('kind','Polysaccharide','glycogen',[['starch','Amylose component of starch'],['glycogen','Glycogen'],['cellulose','Cellulose']]),N('length','Displayed backbone residues',10,4,16)],'Amylose: α(1→4); glycogen: α(1→4) with α(1→6) branches; cellulose: β(1→4).','Stylized glucose residues, not atomic structures. Branch frequency is schematic; starch also includes branched amylopectin. No rate of digestion is predicted.','How can polymers of the same monomer have different biological roles?',s=>{let out='';for(let i=0;i<s.length;i++){let x=80+i*650/(s.length-1);out+=`<rect x="${x-12}" y="185" width="24" height="24" fill="${s.kind==='cellulose'&&i%2?'#b99a55':'#234bb0'}" transform="rotate(${s.kind==='cellulose'&&i%2?45:0} ${x} 197)"/>`;if(i<s.length-1)out+=line(x+12,197,x+650/(s.length-1)-12,197);if(s.kind==='glycogen'&&i%3===1)out+=line(x,185,x,130)+`<circle cx="${x}" cy="115" r="12" fill="#b99a55"/>`;}return output(svg(out+text(410,300,s.kind==='glycogen'?'Branches increase the number of accessible chain ends':s.kind==='cellulose'?'Alternating orientation supports extended chains':'Unbranched amylose can adopt helical conformations',15,'text-anchor="middle"'),390),table(['Polymer','Linkage','Role'],[[s.kind,s.kind==='cellulose'?'β(1→4)':s.kind==='glycogen'?'α(1→4), α(1→6)':'α(1→4)',s.kind==='cellulose'?'Structural':'Energy storage']]))});
