add(2,'water-potential','Water potential','2.7','Compare total water potential, solute potential and pressure in two compartments.',[N('ca','Solute concentration A (mol/L)',.2,0,2,.01),N('ia','Dissociation factor A',1,1,4),N('pa','Pressure potential A (MPa)',.3,-2,3,.01),N('cb','Solute concentration B (mol/L)',.4,0,2,.01),N('ib','Dissociation factor B',1,1,4),N('pb','Pressure potential B (MPa)',0,-2,3,.01),N('temperature','Temperature (°C)',25,0,60)],'Ψ = Ψs + Ψp; Ψs = −iCRT; R = 0.008314 L·MPa·mol⁻¹·K⁻¹.','Ideal solutions, fixed temperature, water-permeable membrane, and no gravity or matric contribution. Output predicts initial direction, not flow rate or final cell volume. Temperature uses °C + 273.15. MPa = bar / 10. Pressure can counteract solute effects.','Can water move toward a compartment with lower solute concentration? Use pressure potential to construct an example.',s=>{const p=potential(s),equal=Math.abs(p.a-p.b)<1e-9;return output(grid([['ΨA',fmt(p.a)+' MPa'],['ΨB',fmt(p.b)+' MPa'],['Net direction',equal?'Equilibrium':p.a>p.b?'A → B':'B → A']]),table(['Compartment','Ψs (MPa)','Ψp (MPa)','Ψ (MPa)'],[['A',fmt(p.sa),fmt(s.pa),fmt(p.a)],['B',fmt(p.sb),fmt(s.pb),fmt(p.b)]]),[['Compartment','Solute potential MPa','Pressure potential MPa','Total potential MPa'],['A',p.sa,s.pa,p.a],['B',p.sb,s.pb,p.b]])});
add(2,'tonicity','Tonicity & cell volume','2.7','Separate osmolarity from tonicity by tracking nonpenetrating solutes.',[N('inside','Internal nonpenetrating solutes (mOsm/L)',300,1,1000),N('outside','External nonpenetrating solutes (mOsm/L)',200,1,1000),N('penetrating','External penetrating solutes (mOsm/L)',0,0,1000),S('cell','Cell type','animal',[['animal','Animal cell'],['plant','Plant cell']])],'Ideal animal-cell equilibrium: Vfinal/Vinitial = Cin/Cout for nonpenetrating solute.','External reservoir is effectively infinite. Internal nonpenetrating solute amount is conserved. Penetrating solute equilibrates and contributes no sustained osmotic gradient in this simplified model. Animal-cell volume prediction ignores rupture. Plant-cell walls and pressure prevent using the animal-volume formula as a plant-cell prediction.','Why can an initially hyperosmotic solution still be hypotonic?',s=>{let ratio=s.inside/s.outside,relation=ratio>1?'Hypotonic':ratio<1?'Hypertonic':'Isotonic',r=45*Math.cbrt(Math.min(8,ratio)),out=`<circle cx="260" cy="240" r="45" fill="#eaf0ff" stroke="#234bb0" stroke-width="2"/>${text(260,340,'Initial',15,'text-anchor="middle"')}`;out+=s.cell==='animal'?`<circle cx="555" cy="240" r="${r}" fill="#eaf0ff" stroke="#234bb0" stroke-width="2"/>`:`<rect x="480" y="165" width="150" height="150" fill="none" stroke="#167568" stroke-width="5"/><circle cx="555" cy="240" r="${ratio<1?r:65}" fill="#eaf0ff" stroke="#234bb0" stroke-width="2"/>`;out+=text(555,340,s.cell==='animal'?'Ideal equilibrium':'Wall-limited schematic',15,'text-anchor="middle"');return output(svg(out,420),metrics([[relation,'External tonicity'],[s.cell==='animal'?fmt(ratio)+'×':'Pressure dependent','Final / initial volume'],[fmt(s.outside+s.penetrating),'Initial external osmolarity (mOsm/L)']])+(ratio>2&&s.cell==='animal'?'<p class="warn">Predicted swelling may exceed membrane tolerance. The model does not simulate lysis.</p>':''))});
function parseRows(raw,mincols=2){const rows=raw.trim().split('\n').map(x=>x.split(/[,;\t ]+/).map(Number));if(rows.length<2||rows.length>100||rows.some(r=>r.length<mincols||r.some(x=>!Number.isFinite(x))))throw Error('Enter 2–100 rows of numeric values with the required columns.');return rows;}ExtraMath.parseRows=parseRows;
add(2,'osmosis-lab','Osmosis data investigation','2.7','Analyze entered tissue measurements and estimate a zero-change concentration.',[T('measurements','Concentration (M), initial mass (g), final mass (g)','0, 2, 2.3\n0.2, 2, 2.1\n0.4, 2, 1.9\n0.6, 2, 1.7','One trial per line; replicate concentrations are allowed.',true),N('temperature','Temperature (°C)',25,0,60)],'% mass change = 100(final − initial)/initial.','Fits an ordinary least-squares line to entered percent changes. The zero crossing is an estimate only when a linear approximation is justified and measurements bracket zero. Assumes an open solution with sucrose (i=1) when calculating its solute potential. Tissue pressure is not inferred.','What does zero net mass change support about the tissue and surrounding solution, and what does it not tell you?',s=>{let r=parseRows(s.measurements,3).map(([x,a,b])=>{if(x<0||a<=0||b<=0)throw Error('Concentration must be nonnegative and masses positive.');return[x,100*(b-a)/a]});let xm=mean(r.map(x=>x[0])),ym=mean(r.map(x=>x[1])),den=r.reduce((v,[x])=>v+(x-xm)**2,0);if(!den)throw Error('Use at least two different concentrations.');let slope=r.reduce((v,[x,y])=>v+(x-xm)*(y-ym),0)/den,intercept=ym-slope*xm,zero=-intercept/slope,bracket=r.some(x=>x[1]<=0)&&r.some(x=>x[1]>=0)&&Number.isFinite(zero)&&zero>=Math.min(...r.map(x=>x[0]))&&zero<=Math.max(...r.map(x=>x[0]));let fit=r.map(([x])=>[x,intercept+slope*x]).sort((a,b)=>a[0]-b[0]);return output(chart([{name:'Entered observations',color:colors()[0],values:r.slice().sort((a,b)=>a[0]-b[0]),points:true},{name:'Linear fit',color:colors()[1],values:fit}],'Sucrose concentration (M)','Mass change (%)'),metrics([[bracket?fmt(zero)+' M':'Not bracketed','Estimated zero-change concentration'],[bracket?fmt(-zero*.008314*(s.temperature+273.15))+' MPa':'—','Solution solute potential at zero crossing']]),[['Concentration M','Percent mass change'],...r])});
add(2,'pumps','Ion gradients & active transport','2.8','Compare a pump’s stoichiometry with the energetic cost of maintaining gradients.',[N('cycles','Na⁺/K⁺ pump cycles',100,1,1000),N('inside','Internal K⁺ (mM)',140,1,200),N('outside','External K⁺ (mM)',5,1,200),N('temperature','Temperature (°C)',37,0,60)],'Na⁺/K⁺ pump: 3 Na⁺ out, 2 K⁺ in per ATP; EK = (RT/F) ln(Kout/Kin).','Stoichiometric pump accounting; ion concentrations do not change from the displayed cycle count. Nernst potential is a college extension for a K⁺-selective membrane and is not the full resting potential.','Why is the Na⁺/K⁺ pump electrogenic, and why is a Nernst equilibrium potential different from a pump rate?',s=>{let ek=8.314*(s.temperature+273.15)/96485*Math.log(s.outside/s.inside)*1000;return output(grid([['Na⁺ outward',3*s.cycles+' ions'],['K⁺ inward',2*s.cycles+' ions'],['ATP used',s.cycles+' ATP'],['Net outward',s.cycles+' charges'],['K⁺ equilibrium',fmt(ek)+' mV']]),table(['Quantity','Value'],[['K⁺ equilibrium potential (mV)',fmt(ek)],['Net charge per ATP','+1 outward']]))});
add(2,'compartments','Compartmentalized reactions','2.9','Compare a protected reaction with one exposed to a competing inhibitor.',[N('substrate','Substrate (mM)',5,.01,100,.01),N('inhibitor','Inhibitor outside compartment (mM)',10,0,100),N('km','Km (mM)',2,.01,100,.01),N('ki','Ki (mM)',2,.01,100,.01),N('vmax','Vmax (µmol/min)',10,.01,100,.01),S('membrane','Compartment boundary','intact',[['intact','Excludes inhibitor'],['leaky','Inhibitor equilibrates']])],'Competitive inhibition: v = Vmax S/[Km(1+I/Ki)+S].','Illustrative reaction with a competitive inhibitor. Boundary condition selects whether inhibitor reaches enzyme; transport rates, volume changes and substrate delivery are not simulated.','Explain how compartmentalization can regulate a reaction without changing the enzyme’s amino-acid sequence.',s=>{let i=s.membrane==='intact'?0:s.inhibitor,v=s.vmax*s.substrate/(s.km*(1+i/s.ki)+s.substrate);return output(grid([['Enzyme compartment',s.membrane==='intact'?'Protected':'Exposed'],['Accessible inhibitor',i+' mM'],['Reaction rate',fmt(v)+' µmol/min']]),metrics([[fmt(v/s.vmax*100)+'%','Fraction of maximal rate']]))});
add(2,'endosymbiosis','Endosymbiosis evidence','2.10','Evaluate which observations support bacterial ancestry of organelles.',[S('evidence','Observation','dna',[['dna','Organelle DNA'],['ribosome','Bacterial-like ribosomes'],['division','Division from pre-existing organelles'],['membrane','Double membranes']])],'A scientific model is evaluated against multiple independent observations.','Evidence explorer, not a historical simulation. Individual observations differ in strength and are not assigned numerical proof scores. Shared features alone do not uniquely establish a full evolutionary sequence.','Which combination of evidence best supports endosymbiosis, and why is one observation alone less conclusive?',s=>{const evidence={dna:['Organelle genomes and sequence relationships','Genetic continuity with bacterial ancestry'],ribosome:['Ribosomes differ from cytosolic eukaryotic ribosomes','Compatibility with bacterial ancestry'],division:['Mitochondria and chloroplasts arise by division','Continuity rather than spontaneous assembly'],membrane:['Two bounding membranes','Consistent with engulfment; not uniquely diagnostic']}[s.evidence];return output(pathDiagram(['Free-living|bacterium','Engulfment|hypothesis','Persistent|association','Organelle|descendants']),table(['Observation','Interpretation'],[evidence]))});
