function enzymeRate(s,Sval=s.substrate){let active=Math.exp(-(((s.ph-s.optimum)/2)**2))*Math.exp(Math.log(2)*(s.temperature-25)/10)/(1+Math.exp((s.temperature-50)/3));let vmax=s.enzyme*s.kcat*active,I=s.inhibitor,km=s.km;if(s.inhibition==='competitive')km*=1+I/s.ki;if(s.inhibition==='noncompetitive')vmax/=1+I/s.ki;if(s.inhibition==='mixed'){km*= (1+I/s.ki)/(1+I/(2*s.ki));vmax/=1+I/(2*s.ki);}return vmax*Sval/(km+Sval);}ExtraMath.enzymeRate=enzymeRate;
add(3,'enzymes','Enzyme investigation studio','3.1–3.2','Explore saturation, product accumulation, inhibitors, temperature and pH.',[S('view','View','substrate',[['substrate','Rate vs substrate'],['progress','Product vs time'],['temperature','Rate vs temperature'],['ph','Rate vs pH']]),N('substrate','Starting substrate (mM)',10,.01,100,.01),N('enzyme','Enzyme concentration (µM)',1,.01,10,.01),N('kcat','Turnover kcat (min⁻¹)',100,1,1000),N('km','Km (mM)',2,.01,50,.01),N('temperature','Temperature (°C)',25,0,80),N('ph','pH',7,1,13,.1),N('optimum','Example enzyme optimum pH',7,2,12,.1),S('inhibition','Inhibitor mechanism','none',[['none','None'],['competitive','Competitive'],['noncompetitive','Pure noncompetitive'],['mixed','Mixed · Ki′ = 2Ki']]),N('inhibitor','Inhibitor (mM)',0,0,50,.1),N('ki','Inhibitor Ki (mM)',2,.01,50,.01),N('time','Reaction time (min)',100,.1,300,.1)],'v = Vmax[S]/(Km+[S]); Vmax = kcat[Eactive].','Michaelis–Menten steady-state model with irreversible product formation and no product inhibition. Enzyme is entered in µM, so rate is µM/min; progress converts to mM/min. Temperature uses a stated illustrative Q10=2 rise with a logistic high-temperature activity loss; pH uses a Gaussian response. These response functions are not measured kinetics or irreversible time-dependent denaturation. Km, kcat and inhibition mechanisms are college extensions.','How can a competitive inhibitor lower rate at one substrate concentration without lowering the saturation limit?',s=>{let rows=[],xlabel='Substrate (mM)',ylabel='Initial rate (µM/min)';if(s.view==='progress'){let progress=integrate([s.substrate,0],([sub])=>{let v=enzymeRate(s,sub)/1000;return[-v,v]},s.time);rows=progress.map(r=>[r[0],r[2]]);xlabel='Time (min)';ylabel='Product (mM)';}else for(let i=0;i<=200;i++){let x=s.view==='temperature'?80*i/200:s.view==='ph'?1+12*i/200:Math.max(10,s.substrate*2)*i/200,ss={...s};if(s.view==='temperature')ss.temperature=x;if(s.view==='ph')ss.ph=x;rows.push([x,enzymeRate(ss,s.view==='substrate'?x:s.substrate)]);}if(s.view==='temperature')xlabel='Temperature (°C)';if(s.view==='ph')xlabel='pH';return output(linearPlot(rows,['Model enzyme response'],xlabel,ylabel),metrics([[fmt(enzymeRate(s))+' µM/min','Initial rate at entered conditions'],[fmt(s.enzyme*s.kcat)+' µM/min','Nominal kcat × total enzyme before activity factors']]),[[xlabel,ylabel],...rows])});
add(3,'activation','Activation energy & catalysis','3.1; 3.3','Change the activation barrier while preserving the reaction’s energy difference.',[N('barrier','Uncatalyzed barrier (kJ/mol)',60,5,150),N('lowering','Enzyme barrier reduction (kJ/mol)',30,0,100),N('dg','Reaction ΔG (kJ/mol)',-20,-60,60)],'Catalysis changes activation energy, not ΔG or the equilibrium constant.','Illustrative reaction-coordinate paths, not measured molecular energy surfaces. Both barriers must exceed reactant and product energy.','Why does an enzyme accelerate both forward and reverse reactions without shifting equilibrium?',s=>{if(s.barrier-s.lowering<=Math.max(0,s.dg))throw Error('Both activation barriers must lie above reactants and products.');const make=b=>Array.from({length:201},(_,i)=>{let x=i/200;return[x,x<=.5?b*Math.sin(Math.PI*x)**2:s.dg+(b-s.dg)*Math.sin(Math.PI*x)**2]});return output(chart([{name:'Without enzyme',color:colors()[0],values:make(s.barrier)},{name:'With enzyme',color:colors()[1],values:make(s.barrier-s.lowering)}],'Reaction coordinate (arbitrary)','Free energy (kJ/mol)'),metrics([[s.dg+' kJ/mol','Unchanged reaction ΔG'],[(s.barrier-s.lowering)+' kJ/mol','Entered catalyzed barrier parameter']]))});
add(3,'coupling','ATP coupling & feedback','3.3','Account for energy in coupled reactions and explore end-product feedback.',[N('required','Energy-requiring reaction ΔG (kJ/mol)',20,-50,100),N('atp','ATP hydrolysis ΔG (kJ/mol)',-30.5,-80,-1,.1),N('count','ATP molecules coupled',1,1,5),S('feedback','End-product condition','low',[['low','Low product'],['high','High product inhibits first enzyme']])],'ΔGcoupled = ΔGreaction + nΔGATP.','Energetic bookkeeping assumes reactions are mechanistically coupled. ATP free-energy change is entered for the conditions and is not a universal constant. Feedback is a qualitative pathway example.','Why does putting ATP beside an endergonic reaction not guarantee that the reaction is driven?',s=>{let total=s.required+s.count*s.atp;return output(pathDiagram(['Starting substrate','Regulated enzyme','Intermediate','End product'],[true,s.feedback==='low',s.feedback==='low',true],s.feedback==='high'?'End product feeds back to inhibit the regulated step':'Low end-product inhibition'),metrics([[fmt(total)+' kJ/mol','Coupled ΔG'],[total<0?'Favorable':total>0?'Unfavorable':'Equilibrium','Thermodynamic direction at entered conditions']]))});
add(3,'photosystems','Photosynthesis & electron flow','3.4','Trace light-driven electron transfer and resource limits on carbon fixation.',[N('light','Available photon events / interval',80,0,1000),N('co2','CO₂ available / interval',10,0,100),S('block','Perturbation','none',[['none','None'],['psii','Photosystem II blocked'],['psi','Photosystem I blocked'],['atp','ATP synthase blocked'],['calvin','Carbon fixation blocked']])],'Canonical linear flow: 8 photons → 4 electrons → 2 NADPH; Calvin cycle: 3 CO₂ + 9 ATP + 6 NADPH per net G3P.','Stoichiometric upper-bound teaching model. Uses an assumed 3 ATP per 8 photons for bookkeeping; actual ATP production depends on coupling and cyclic electron flow. Does not simulate carbon-fixation kinetics, photorespiration, or absorbed-light efficiency. Blocking ATP synthase can also impede electron flow; that feedback is not dynamically modeled.','Predict why light reactions can be affected when the Calvin cycle stops consuming ATP and NADPH.',s=>{let flow=['psii','psi'].includes(s.block)?0:s.light/8,nadph=flow*2,atp=s.block==='atp'?0:flow*3,g3p=s.block==='calvin'?0:Math.min(s.co2/3,atp/9,nadph/6);return output(branchingDiagram([[60,100,'Water → PSII',s.block!=='psii'],[240,100,'Electron transport',flow>0],[420,100,'PSI',flow>0],[600,100,'NADPH',nadph>0],[240,240,'H⁺ gradient',flow>0],[420,240,'ATP synthase',atp>0],[600,240,'ATP',atp>0],[420,370,'Calvin cycle|carbon fixation',g3p>0]],[[[210,132],[240,132]],[[390,132],[420,132]],[[570,132],[600,132]],[[315,165],[315,240]],[[390,272],[420,272]],[[570,272],[600,272]],[[750,132],[790,132],[790,400],[570,400]],[[675,305],[675,400],[570,400]]],'Electron flow generates reducing power; proton flow drives ATP synthesis.'),metrics([[fmt(nadph),'NADPH upper bound / interval'],[fmt(atp),'ATP upper bound / interval'],[fmt(g3p),'Net G3P upper bound / interval']]))});
add(3,'light-response','Photosynthesis investigation','3.4','Explore net photosynthesis, light saturation and the compensation point.',[N('pmax','Maximum gross rate (µmol O₂/min)',20,.1,100,.1),N('half','Half-saturation irradiance',100,1,1000),N('respiration','Respiration rate (µmol O₂/min)',3,0,50,.1),N('light','Maximum irradiance shown',600,10,2000),S('view','View','light',[['light','Light-response curve'],['disks','Illustrative leaf-disk float fraction']])],'Net rate = Pmax I/(H+I) − R.','Empirical saturating response with constant respiration. Irradiance is in relative units. Leaf-disk view maps accumulated net gas to float fraction using an explicit illustrative threshold distribution; it is not a calibrated prediction for real disks. Pigment composition, CO₂ limitation and photoinhibition are outside this model.','At the compensation point, is photosynthesis absent or balanced by another process?',s=>{let rows=Array.from({length:201},(_,i)=>{let x=s.light*i/200,net=s.pmax*x/(s.half+x)-s.respiration;return[x,net]});if(s.view==='disks'){const net=Math.max(0,s.pmax*s.light/(s.half+s.light)-s.respiration);rows=Array.from({length:201},(_,i)=>{let t=i/10;return[t,100*(1-Math.exp(-net*t/50))]});}let compensation=s.pmax>s.respiration?s.respiration*s.half/(s.pmax-s.respiration):null;return output(linearPlot(rows,[s.view==='disks'?'Illustrative float fraction':'Net photosynthesis'],s.view==='disks'?'Time (min)':'Relative irradiance',s.view==='disks'?'Floating disks (%)':'Net O₂ rate (µmol/min)'),metrics([[compensation===null?'No finite point':fmt(compensation),'Light compensation point (relative irradiance)']]),[['X','Response'],...rows])});
