add(4,'signaling','Signal transduction & amplification','4.3','Perturb a cascade and compare upstream and downstream effects.',[N('input','Activated receptors',5,0,100),N('amplification','Amplification per stage',3,1,10),S('block','Disruption','none',[['none','None'],['receptor','Receptor unavailable'],['relay','Relay kinase blocked'],['effector','Effector blocked'],['constitutive','Relay constitutively active']])],'Activated receptor → relay → effector → cellular response.','Discrete illustrative cascade with a 10,000-unit response ceiling. Amplification units are arbitrary and not fitted biochemical rate constants. Constitutive relay activation bypasses the receptor but does not bypass an effector block.','Which mutation could produce a response without ligand, and which intervention would still block it?',s=>{let receptor=s.block==='receptor'?0:s.input,relay=s.block==='relay'?0:s.block==='constitutive'?10:receptor*s.amplification,effector=s.block==='effector'?0:relay*s.amplification,response=Math.min(10000,effector*s.amplification);return output(pathDiagram([`Receptor|${receptor}`,`Relay|${relay}`,`Effector|${effector}`,`Response|${response}`],[receptor>0,relay>0,effector>0,response>0]),metrics([[response,'Illustrative response units']]))});
add(4,'feedback','Feedback & homeostasis','4.4','Compare restorative negative feedback with self-amplification under explicit limits.',[S('type','Feedback','negative',[['negative','Negative feedback'],['positive','Positive feedback']]),N('initial','Initial deviation from set point',10,.1,50,.1),N('gain','Response gain (time⁻¹)',.4,.01,2,.01),N('ceiling','Positive-feedback capacity',40,1,100),N('time','Time span',20,.1,100,.1)],'Negative: dx/dt = −kx; positive example: dx/dt = kx(1−x/L).','Deviation magnitude is nonnegative. The positive example is bounded amplification, not a model of every biological positive-feedback system. The positive ceiling is a saturation limit, not a homeostatic set point. No delay or oscillatory controller is included.','Explain why a response that increases an initial deviation can still terminate.',s=>{let rows=Array.from({length:201},(_,i)=>{let t=s.time*i/200;return[t,s.type==='negative'?s.initial*Math.exp(-s.gain*t):s.ceiling/(1+(s.ceiling/s.initial-1)*Math.exp(-s.gain*t))]});return output(linearPlot(rows,['Deviation magnitude'],'Time (model units)','Deviation (model units)'),metrics([[fmt(rows.at(-1)[1]),'Final deviation']]),[['Time','Deviation'],...rows])});
add(4,'cell-cycle','Cell cycle, DNA content & mitosis','4.5','Track chromosome counting, DNA replication and daughter-cell outcomes.',[N('haploid','Haploid chromosome number n',3,1,12),S('stage','Stage','g1',[['g1','G₁'],['s','End of S phase'],['g2','G₂'],['metaphase','Metaphase'],['anaphase','Anaphase · one undivided cell'],['daughter','After cytokinesis · one daughter']])],'DNA replication doubles DNA content; chromosome number depends on centromere counting.','Diploid cell with conventional mitosis. Anaphase counts separated sister chromatids as chromosomes within the still-undivided cell. C indicates DNA content relative to one unreplicated haploid genome.','Why does G₂ have twice the DNA content of G₁ without twice the chromosome number?',s=>{const replicated=!['g1','daughter'].includes(s.stage),chrom=s.stage==='anaphase'?4*s.haploid:2*s.haploid,dna=replicated?4:2;let body='';for(let i=0;i<Math.min(chrom,24);i++){let x=100+i%8*85,y=120+Math.floor(i/8)*80;if(replicated&&s.stage!=='anaphase')body+=line(x-12,y-20,x+12,y+20,colors()[i<s.haploid?0:1],'style="stroke-width:4"')+line(x+12,y-20,x-12,y+20,colors()[i<s.haploid?0:1],'style="stroke-width:4"');else body+=line(x,y-20,x,y+20,colors()[i<s.haploid?0:1],'style="stroke-width:4"');}return output(svg(body+text(410,420,`${s.stage} · ${chrom} chromosomes · ${dna}C DNA · centromere counting`,15,'text-anchor="middle"')),metrics([[chrom,'Chromosomes in displayed cell'],[dna+'C','DNA content'],[s.stage==='anaphase'?'Each pole: 2n':'2n','Chromosome sets / daughter interpretation']]))});
add(4,'mitotic-index','Mitotic-index investigation','4.5','Estimate phase fractions and durations from an asynchronously dividing population.',[N('interphase','Interphase cells',80,0,10000),N('prophase','Prophase cells',10,0,10000),N('metaphase','Metaphase cells',5,0,10000),N('anaphase','Anaphase cells',2,0,10000),N('telophase','Telophase cells',3,0,10000),N('cycle','Assumed cycle duration (hours)',24,.1,100,.1)],'Phase fraction = cells in phase / total; estimated duration = fraction × cycle duration.','Duration inference assumes a steady-state asynchronous population with comparable survival and sampling. A synchronized population or changing proliferation can invalidate the estimate.','Why would a drug arresting cells in metaphase make a duration estimate misleading?',s=>{let phases=['interphase','prophase','metaphase','anaphase','telophase'],total=phases.reduce((a,k)=>a+s[k],0);if(!total)throw Error('Count at least one cell.');return output(grid(phases.map(k=>[k,pct(s[k]/total)])),table(['Phase','Cells','Fraction','Estimated hours'],phases.map(k=>[k,s[k],pct(s[k]/total),fmt(s[k]/total*s.cycle)])),[['Phase','Cells','Fraction','Estimated hours'],...phases.map(k=>[k,s[k],s[k]/total,s[k]/total*s.cycle])])});
