add(5,'meiosis','Meiosis & nondisjunction','5.1–5.2','Track reduction division, chromosome assortment and stage-specific nondisjunction.',[N('haploid','Haploid number n',3,1,12),S('error','Segregation','none',[['none','Normal meiosis'],['i','One homolog pair fails in meiosis I'],['ii','One sister pair fails in meiosis II']]),S('stage','Displayed process','gametes',[['gametes','Gamete chromosome counts'],['division','Division sequence']])],'Normal gametes: n chromosomes; independent assortment permits 2ⁿ chromosome combinations before crossing over.','One nondisjunction event in one chromosome pair is assumed. Crossing over is not included in the combination count. Meiosis II error occurs in one of the two cells. Gamete types are equally represented in this schematic.','Why does meiosis I nondisjunction produce no normal gametes for the affected chromosome?',s=>{let counts=s.error==='none'?Array(4).fill(s.haploid):s.error==='i'?[s.haploid+1,s.haploid+1,s.haploid-1,s.haploid-1]:[s.haploid,s.haploid,s.haploid+1,s.haploid-1];return output(s.stage==='division'?pathDiagram(['Diploid cell|2n, 2C','DNA replication|2n, 4C','Meiosis I|n, 2C','Meiosis II|n, 1C'],[true,true,true,true],s.error==='none'?'Normal reference sequence':'Normal reference sequence; select gamete view for the chosen error'):grid(counts.map((v,i)=>['Gamete '+(i+1),v+' chromosomes'])),metrics([[2**s.haploid,'Assortment combinations before crossing over'],[counts.filter(x=>x===s.haploid).length+'/4','Normal chromosome-count gametes']]),[['Gamete','Chromosomes'],...counts.map((x,i)=>[i+1,x])])});
add(5,'linkage','Linkage & recombination','5.2; 5.4','Predict a two-locus testcross and compare observed recombinants.',[N('rf','Recombination fraction',.2,0,.5,.01),S('phase','Heterozygote phase','coupling',[['coupling','AB / ab'],['repulsion','Ab / aB']]),N('total','Testcross offspring',1000,1,100000),N('observed','Observed recombinant offspring',200,0,100000)],'Each parental class has probability (1−r)/2; each recombinant class has r/2.','Testcross to ab/ab with equal viability and no segregation distortion. Recombination fraction cannot exceed 0.5. Recombination percentage approximates map distance for short intervals; multiple crossovers cause underestimation for longer intervals.','Why can genes on the same chromosome appear to assort independently when they are far apart?',s=>{if(s.observed>s.total)throw Error('Recombinants cannot exceed total offspring.');const parental=s.phase==='coupling'?['AB','ab']:['Ab','aB'],recomb=s.phase==='coupling'?['Ab','aB']:['AB','ab'],rows=[...parental.map(x=>[x,'Parental',(1-s.rf)/2]),...recomb.map(x=>[x,'Recombinant',s.rf/2])];return output(grid(rows.map(([g,k,p])=>[g+' · '+k,pct(p)])),table(['Gamete','Class','Probability','Expected count'],rows.map(([g,k,p])=>[g,k,pct(p),fmt(p*s.total)]))+metrics([[pct(s.observed/s.total),'Observed recombination fraction']]),[['Gamete','Class','Probability','Expected count'],...rows.map(([g,k,p])=>[g,k,p,p*s.total])])});
add(5,'nonmendelian','Multiple alleles & epistasis','5.4','Compare an ABO cross with a defined recessive-epistasis example.',[S('example','Example','abo',[['abo','ABO blood-group cross'],['epistasis','AaBb × AaBb · aa masks B']]),S('parent1','ABO parent 1','AO',[['AA','IAIA'],['AO','IAi'],['BB','IBIB'],['BO','IBi'],['AB','IAIB'],['OO','ii']]),S('parent2','ABO parent 2','BO',[['AA','IAIA'],['AO','IAi'],['BB','IBIB'],['BO','IBi'],['AB','IAIB'],['OO','ii']])],'Dominance relationships and gene interactions determine phenotype from genotype.','ABO uses the standard simplified single-locus model; rare exceptions are excluded. Epistasis example defines aa as masking the B locus, giving 9:3:4 under independent assortment and equal viability.','Why does a changed phenotype ratio not necessarily imply altered allele segregation?',s=>{let result={};if(s.example==='epistasis')result={'A_B_':9/16,'A_bb':3/16,'aa__ (masked)':4/16};else for(const a of s.parent1)for(const b of s.parent2){let p=a==='O'&&b==='O'?'O':new Set([a,b]).has('A')&&new Set([a,b]).has('B')?'AB':[a,b].includes('A')?'A':'B';result[p]=(result[p]||0)+.25;}return output(grid(Object.entries(result).map(([p,v])=>[p,pct(v)])),table(['Phenotype','Probability'],Object.entries(result).map(([p,v])=>[p,pct(v)])),[['Phenotype','Probability'],...Object.entries(result)])});
add(5,'polygenic','Polygenic trait distributions','5.4','Separate additive allele effects from environmental spread.',[N('loci','Independent additive loci',3,1,8),N('effect','Trait units per contributing allele',1,.1,10,.1),N('environment','Environmental SD (trait units)',.5,.05,5,.05)],'For equal-frequency additive alleles, contributing allele count follows Binomial(2n, 0.5).','Two heterozygous parents at every independent locus; additive equal effects; no epistasis or dominance. Environment adds independent normally distributed variation. These assumptions do not describe every quantitative trait.','How can a continuously distributed trait still arise from discrete alleles?',s=>{let n=2*s.loci,rows=[];for(let i=0;i<=250;i++){let x=-3*s.environment+(n*s.effect+6*s.environment)*i/250,v=0;for(let k=0;k<=n;k++)v+=choose(n,k)/2**n*normal(x,k*s.effect,s.environment);rows.push([x,v]);}return output(linearPlot(rows,['Genotype mixture + environment'],'Trait value (model units)','Probability density'),metrics([[fmt(s.loci*s.effect),'Expected trait mean'],[fmt(Math.sqrt(n*.25*s.effect**2+s.environment**2)),'Expected trait SD']]),[['Trait','Density'],...rows])});
