function digest(d,enzyme,circular){let motif={EcoRI:'GAATTC',BamHI:'GGATCC',HindIII:'AAGCTT'}[enzyme],scan=circular?d+d.slice(0,5):d,cuts=[];for(let i=0;i<d.length;i++)if(scan.slice(i,i+6)===motif)cuts.push((i+1)%d.length);cuts.sort((a,b)=>a-b);let sizes;if(!cuts.length)sizes=[d.length];else if(circular)sizes=cuts.map((x,i)=>i===cuts.length-1?d.length-x+cuts[0]:cuts[i+1]-x);else{const bounds=[0,...cuts.filter(x=>x>0),d.length];sizes=bounds.slice(1).map((x,i)=>x-bounds[i]);}return{cuts,sizes,motif};}ExtraMath.digest=digest;
