function alleleSelection(p,wAA,wAa,waa){const q=1-p,weights=[p*p*wAA,2*p*q*wAa,q*q*waa],w=weights.reduce((a,b)=>a+b,0);if(!w)throw Error('Mean fitness is zero; no reproducing population remains.');return{p:(weights[0]+weights[1]/2)/w,w};}ExtraMath.alleleSelection=alleleSelection;
add(7,'selection','Selection & resistance evolution','7.1–7.2; 7.8','Change genotype fitness and track an allele over generations.',[N('p','Initial A allele frequency',.1,0,1,.01),N('waa','Fitness AA',1,0,2,.01),N('wah','Fitness Aa',.9,0,2,.01),N('wrr','Fitness aa',.5,0,2,.01),N('generations','Generations',50,1,200),S('scenario','Interpretation','general',[['general','General natural selection'],['resistance','A represents a resistance-associated allele']])],'p′ = (p²wAA + pqwAa)/w̄; w̄ = p²wAA + 2pqwAa + q²waa.','Infinite diploid population, random mating, constant viability selection, no drift, mutation or migration. Resistance scenario is a conceptual allele-fitness example, not a bacterial clinical or treatment model.','Why can a beneficial recessive allele increase slowly when initially rare?',s=>{let p=s.p,rows=[[0,p,1-p]];for(let i=1;i<=s.generations;i++){p=alleleSelection(p,s.waa,s.wah,s.wrr).p;rows.push([i,p,1-p]);}return output(linearPlot(rows,['A frequency','a frequency'],'Generation','Allele frequency'),metrics([[fmt(p),'Final A frequency'],[s.scenario,'Scenario label']]),[['Generation','p','q'],...rows])});
add(7,'trait-selection','Selection on trait distributions','7.2; 7.11','Compare directional, stabilizing and disruptive fitness functions.',[S('type','Selection','directional',[['directional','Directional'],['stabilizing','Stabilizing'],['disruptive','Disruptive']]),N('strength','Selection strength',1,0,3,.1)],'Selected trait density ∝ initial density × relative fitness.','One generation of selection on a normally distributed standardized trait. Fitness functions are explicit teaching examples: exp(sx), exp(−sx²), or 1+sx². No inheritance response or universal ecological optimum is inferred.','How can selection alter variance without strongly changing the mean?',s=>{let rows=[];for(let i=0;i<=200;i++){let x=-4+8*i/200,f=s.type==='directional'?Math.exp(s.strength*x):s.type==='stabilizing'?Math.exp(-s.strength*x*x):1+s.strength*x*x;rows.push([x,normal(x,0,1),normal(x,0,1)*f]);}let area=rows.reduce((a,r)=>a+r[2]*.04,0);rows.forEach(r=>r[2]/=area);return output(linearPlot(rows,['Before selection','After selection'],'Standardized trait','Probability density'),table(['Selection','Fitness function'],[[s.type,s.type==='directional'?'exp(sx)':s.type==='stabilizing'?'exp(−sx²)':'1+sx²']]),[['Trait','Before density','After density'],...rows])});
add(7,'artificial','Artificial selection response','7.3','Explore how heritability and breeder selection affect an expected response.',[N('initial','Initial trait mean',10,-100,100),N('selected','Selected-parent mean',14,-100,100),N('heritability','Narrow-sense heritability h²',.5,0,1,.01),N('generations','Generations with constant differential',10,1,30)],'Breeder’s equation extension: R = h²S.','College extension: quantitative-genetic expectation under additive inheritance and stable environment. Selection differential is fixed relative to the changing population mean each generation. Heritability is population/environment-specific and does not measure how genetically determined an individual trait is.','Why can identical selection differentials produce different responses in two populations?',s=>{let Sval=s.selected-s.initial,R=s.heritability*Sval,rows=Array.from({length:s.generations+1},(_,i)=>[i,s.initial+i*R]);return output(linearPlot(rows,['Expected population mean'],'Generation','Trait mean (model units)'),metrics([[fmt(Sval),'Selection differential'],[fmt(R),'Expected response per generation']]),[['Generation','Expected trait mean'],...rows])});
add(7,'drift','Genetic drift, founders & bottlenecks','7.4','Run a reproducible Wright–Fisher sample through generations.',[N('p','Initial allele frequency',.5,0,1,.01),N('population','Diploid population size N',100,2,2000),N('generations','Generations',60,1,200),N('seed','Random seed',42,1,1000000),S('event','Initial sampling event','none',[['none','None'],['founder','Founder sample'],['bottleneck','Bottleneck']]),N('eventsize','Diploid founder/bottleneck size',10,2,2000)],'Each generation samples 2N allele copies: count ∼ Binomial(2N,p).','Neutral Wright–Fisher model with discrete nonoverlapping generations, no migration, selection or mutation. Founder/bottleneck changes the initial sampled allele pool once; subsequent generations use the entered N. Seed fixes reproducibility.','Why does a different seed produce a different direction of change under the same conditions?',s=>{let rng=seeded(s.seed),p=s.p,rows=[[0,p]];if(s.event!=='none')p=sampleBinomial(2*s.eventsize,p,rng)/(2*s.eventsize);for(let i=1;i<=s.generations;i++){p=sampleBinomial(2*s.population,p,rng)/(2*s.population);rows.push([i,p]);}return output(linearPlot(rows,['Neutral A frequency'],'Generation','Allele frequency'),metrics([[fmt(p),'Final allele frequency'],[p===0?'Lost':p===1?'Fixed':'Segregating','Allele status']]),[['Generation','p'],...rows])});
add(7,'gene-flow','Gene flow between populations','7.4','Track allele-frequency convergence when migrants replace residents.',[N('pa','Population A initial p',.9,0,1,.01),N('pb','Population B initial p',.1,0,1,.01),N('migration','Symmetric migrant fraction',.05,0,.5,.01),N('generations','Generations',40,1,200)],'pA′ = (1−m)pA + mpB; pB′ = (1−m)pB + mpA.','Equal-sized infinite populations with symmetric replacement migration, no selection or drift. Frequency changes are calculated simultaneously each generation.','Why does gene flow tend to reduce differences between populations while adding variation within a population?',s=>{let a=s.pa,b=s.pb,rows=[[0,a,b]];for(let i=1;i<=s.generations;i++){let aa=(1-s.migration)*a+s.migration*b,bb=(1-s.migration)*b+s.migration*a;a=aa;b=bb;rows.push([i,a,b]);}return output(linearPlot(rows,['Population A','Population B'],'Generation','A allele frequency'),metrics([[fmt(Math.abs(a-b)),'Final difference in p']]),[['Generation','pA','pB'],...rows])});
add(7,'hardy','Hardy–Weinberg equilibrium','7.5','Derive allele frequencies from genotype counts and compare equilibrium expectations.',[N('aa','Observed AA',36,0,100000),N('ah','Observed Aa',48,0,100000),N('rr','Observed aa',16,0,100000)],'p = (2AA+Aa)/(2N); expected frequencies: p², 2pq, q².','Diploid biallelic locus. Frequency comparison is descriptive and does not identify a cause of departure. Allele frequency is estimated from the same sample; a formal HWE chi-square test therefore has one degree of freedom and can be unreliable with small expected counts.','Why does matching Hardy–Weinberg genotype proportions not establish that no evolutionary force has ever acted?',s=>{let total=s.aa+s.ah+s.rr;if(!total)throw Error('Enter at least one individual.');let p=(2*s.aa+s.ah)/(2*total),q=1-p,expected=[p*p*total,2*p*q*total,q*q*total],obs=[s.aa,s.ah,s.rr],chi=expected.reduce((a,e,i)=>a+(e?(obs[i]-e)**2/e:0),0);return output(grid([['p',fmt(p)],['q',fmt(q)],['Expected 2pq',pct(2*p*q)]]),table(['Genotype','Observed','Expected HWE count'],['AA','Aa','aa'].map((g,i)=>[g,obs[i],fmt(expected[i])]))+metrics([[fmt(chi),'Descriptive χ² statistic']]),[['Genotype','Observed','Expected'],...['AA','Aa','aa'].map((g,i)=>[g,obs[i],expected[i]])])});
add(7,'sequence-evidence','Evolutionary sequence evidence','7.6–7.7','Compare equal-length sequences while separating similarity from historical inference.',[T('a','Sequence A','ATGCCGTTAACG'),T('b','Sequence B','ATGACGTTAATG')],'p-distance = differing aligned positions / compared positions.','Assumes a valid alignment of equal-length homologous sequences. p-distance is uncorrected for multiple substitutions and is not a phylogenetic reconstruction method. Similarity alone does not establish orthology or ancestral direction.','Why can two lineages show the same observed differences despite different numbers of historical substitutions?',s=>{let a=seq(s.a),b=seq(s.b);if(a.length!==b.length)throw Error('Use equal-length aligned sequences.');let mismatch=a.split('').filter((x,i)=>x!==b[i]).length;return output(sequenceFigure([['Aligned A',a],['Aligned B',b],['Differences',''.padEnd(a.length,' ').split('').map((_,i)=>a[i]===b[i]?'.':'^').join('')]],'Dots = same base; carets = differences.'),metrics([[mismatch,'Different aligned positions'],[fmt(mismatch/a.length),'Uncorrected p-distance']]),[['Sequence A','Sequence B','Mismatches','p-distance'],[a,b,mismatch,mismatch/a.length]])});
add(7,'phylogeny','Phylogenetic-tree studio','7.9','Rotate branches, compare relationships and identify a most recent common ancestor.',[S('topology','Rooted topology','ab',[['ab','((A,B),(C,D))'],['ac','((A,C),(B,D))'],['ladder','(A,(B,(C,D)))']]),S('rotate','Rotate displayed tips','no',[['no','Reference ordering'],['yes','Rotate sibling order']]),S('pair','Pair to compare','AB',[['AB','A and B'],['AC','A and C'],['CD','C and D']])],'Rotating branches at a node preserves relationships.','Four-taxon rooted cladograms with no branch-length time or genetic-distance scale. Internal nodes represent inferred ancestors; none of the tip species is labeled as another tip’s ancestor.','Why can two differently arranged trees represent exactly the same relationships?',s=>{let order=s.topology==='ac'?['A','C','B','D']:['A','B','C','D'];if(s.rotate==='yes')order=[order[1],order[0],order[3],order[2]];let out=line(110,240,250,240,'#234bb0'),ys=[110,195,285,370];if(s.topology==='ladder'){let index=Object.fromEntries(order.map((x,i)=>[x,ys[i]]));let cd=(index.C+index.D)/2,bcd=(index.B+cd)/2;out=line(110,(index.A+bcd)/2,250,(index.A+bcd)/2,'#234bb0')+line(250,index.A,250,bcd,'#234bb0')+line(250,index.A,650,index.A,'#234bb0')+line(250,bcd,400,bcd,'#234bb0')+line(400,index.B,400,cd,'#234bb0')+line(400,index.B,650,index.B,'#234bb0')+line(400,cd,540,cd,'#234bb0')+line(540,index.C,540,index.D,'#234bb0')+line(540,index.C,650,index.C,'#234bb0')+line(540,index.D,650,index.D,'#234bb0');}else{out+=line(250,(ys[0]+ys[1])/2,250,(ys[2]+ys[3])/2,'#234bb0');for(let j=0;j<2;j++){let mid=(ys[j*2]+ys[j*2+1])/2;out+=line(250,mid,450,mid,'#234bb0')+line(450,ys[j*2],450,ys[j*2+1],'#234bb0');for(let k=0;k<2;k++)out+=line(450,ys[j*2+k],650,ys[j*2+k],'#234bb0');}}order.forEach((x,i)=>out+=text(675,ys[i]+5,x,18));let sister=s.topology==='ac'?['AC','BD'].includes(s.pair):s.topology==='ladder'?s.pair==='CD':['AB','CD'].includes(s.pair);return output(svg(out,450),table(['Selected pair','Relationship'],[[s.pair,sister?'Sister tips in this topology':'Share a deeper common ancestor']]))});
add(7,'speciation','Isolation & divergence','7.10–7.11','Compare opposing local selection with migration between populations.',[N('pa','Population A initial p',.5,.001,.999,.001),N('pb','Population B initial p',.5,.001,.999,.001),N('selection','Opposing selection strength',.2,0,.9,.01),N('migration','Migrant fraction',.01,0,.5,.01),N('generations','Generations',80,1,200)],'Local allele selection followed by symmetric migration.','Infinite two-population allele model: A favored in one population and a favored in the other with additive genotype fitness. Frequency divergence does not itself establish reproductive isolation or a new species.','What additional evidence would be needed to call two divergent populations separate species?',s=>{let a=s.pa,b=s.pb,r=[[0,a,b]];for(let i=1;i<=s.generations;i++){let aa=alleleSelection(a,1,1-s.selection/2,1-s.selection).p,bb=alleleSelection(b,1-s.selection,1-s.selection/2,1).p;a=(1-s.migration)*aa+s.migration*bb;b=(1-s.migration)*bb+s.migration*aa;r.push([i,a,b]);}return output(linearPlot(r,['Population A','Population B'],'Generation','A allele frequency'),metrics([[fmt(Math.abs(a-b)),'Final allele-frequency divergence']]),[['Generation','pA','pB'],...r])});
add(7,'origins','Origins-of-life evidence','7.12','Evaluate experimental support and limits of early-life hypotheses.',[S('evidence','Evidence scenario','organic',[['organic','Abiotic organic-molecule formation'],['rna','Catalytic RNA'],['vesicles','Spontaneous lipid vesicles']])],'Evidence can support a plausible mechanism without identifying a unique historical pathway.','Curated reasoning activity, not a reconstruction of the origin of life. Experimental possibility does not prove that an exact laboratory condition or sequence occurred on early Earth.','What does the experiment demonstrate directly, and which historical claim would require additional evidence?',s=>{const e={organic:['Organic molecules can form under some abiotic conditions','Does not establish the precise early-Earth atmosphere or a full path to life'],rna:['Some RNA can catalyze reactions','Supports possible combined information/catalysis roles; does not demonstrate a complete first organism'],vesicles:['Amphipathic molecules can self-assemble into compartments','Supports compartment formation; does not alone demonstrate heredity or metabolism']}[s.evidence];return output(pathDiagram(['Experimental|conditions','Observed|process','Plausible|mechanism','Historical|hypothesis'],[true,true,true,false],'Historical interpretation requires additional evidence.'),table(['Direct support','Limit'],[e]))});
