add(8,'behavior','Environmental responses: taxis & kinesis','8.1','Compare directed movement with position-dependent random activity.',[S('kind','Behavior','taxis',[['taxis','Positive taxis toward cue'],['kinesis','Kinesis · slower where cue is stronger'],['random','Random movement baseline']]),N('agents','Individuals',40,5,150),N('steps','Movement steps',100,5,300),N('seed','Random seed',42,1,1000000)],'Taxis changes directional bias; kinesis changes activity without orienting toward a cue.','One-dimensional bounded arena; cue increases left to right. Reflecting boundaries prevent escape. Taxis adds a positive directional bias; kinesis changes random step size. Output is an illustrative behavioral model, not fitted animal behavior.','How can animals accumulate in favorable conditions without moving directionally toward them?',s=>{const rng=seeded(s.seed),initial=Array.from({length:s.agents},()=>rng()*100),pos=initial.slice();for(let step=0;step<s.steps;step++)for(let j=0;j<pos.length;j++){let speed=s.kind==='kinesis'?6*(1-pos[j]/100)+.5:4,delta=(rng()-.5)*speed+(s.kind==='taxis'?1:0),p=pos[j]+delta;pos[j]=p<0?-p:p>100?200-p:p;}let out=line(80,320,740,320)+text(80,365,'Weak cue',14)+text(650,365,'Strong cue',14);pos.forEach((p,i)=>out+=`<circle cx="${80+p*6.6}" cy="${110+(i%10)*18}" r="4" fill="#234bb0"/>`);return output(svg(out,420),metrics([[fmt(mean(initial)),'Initial mean position'],[fmt(mean(pos)),'Final mean position']]),[['Individual','Initial position','Final position'],...pos.map((p,i)=>[i+1,initial[i],p])])});
add(8,'energy-flow','Trophic energy & productivity','8.2','Account for gross productivity, respiration and transfer between trophic levels.',[N('gross','Gross primary productivity (kJ/m²/day)',10000,1,100000),N('respiration','Producer respiration (kJ/m²/day)',4000,0,100000),N('efficiency','Transfer efficiency (%)',10,1,40),N('levels','Trophic levels including producers',4,2,5)],'NPP = GPP − producer respiration; available energy next level = current level × efficiency.','Steady-state energy-accounting example. Constant transfer efficiency is an entered assumption, not a universal 10% rule. Producer respiration cannot exceed GPP in this nonnegative-NPP view. Biomass and numbers are not calculated directly from energy.','Why can energy availability limit the length of a food chain even though matter is recycled?',s=>{if(s.respiration>s.gross)throw Error('Producer respiration must not exceed GPP for this view.');let npp=s.gross-s.respiration,rows=Array.from({length:s.levels},(_,i)=>[i+1,npp*(s.efficiency/100)**i]);let out='';rows.forEach(([level,e],i)=>{let width=Math.max(25,650*(e/(npp||1))**.35),x=410-width/2,y=85+(s.levels-1-i)*68;out+=`<rect x="${x}" y="${y}" width="${width}" height="50" fill="${colors()[0]}" opacity="${.5+i*.1}"/>${text(410,y+31,`Level ${level}: ${fmt(e)} kJ/m²/day`,14,'text-anchor="middle"')}`});out+=text(410,100+s.levels*68,'Schematic pyramid: widths are not proportional to energy.',12,'text-anchor="middle"');return output(svg(out,130+s.levels*68),metrics([[fmt(npp),'Net primary productivity (kJ/m²/day)']]),[['Trophic level','Energy kJ per square meter per day'],...rows])});
add(8,'matter-cycle','Carbon, nitrogen & phosphorus pools','8.2','Track conserved matter as it cycles through environment, producers and consumers.',[S('element','Element','carbon',[['carbon','Carbon'],['nitrogen','Nitrogen'],['phosphorus','Phosphorus']]),N('environment','Environment pool (model mass)',100,0,1000),N('producers','Producer pool (model mass)',20,0,1000),N('consumers','Consumer pool (model mass)',10,0,1000),N('uptake','Uptake rate (time⁻¹)',.05,0,1,.01),N('feeding','Consumption rate (time⁻¹)',.05,0,1,.01),N('return','Return rate (time⁻¹)',.1,0,1,.01),N('time','Time span',50,.1,200,.1)],'Environment → producers → consumers → environment, with producer return.','Closed three-pool accounting model. Uptake applies to the chosen available chemical pool; nitrogen fixation, nitrification and phosphorus weathering are not resolved separately. Energy is not represented by this conserved pool.','Why does a conserved total not imply that every organism has access to the element it needs?',s=>{let r=integrate([s.environment,s.producers,s.consumers],([e,p,c])=>[-s.uptake*e+s.return*(p+c),s.uptake*e-s.feeding*p-s.return*p,s.feeding*p-s.return*c],s.time);return output(linearPlot(r,['Environment','Producers','Consumers'],'Time (model units)',s.element+' pool (model mass)'),metrics([[fmt(s.environment+s.producers+s.consumers),'Conserved total matter']]),[['Time','Environment','Producers','Consumers'],...r])});
add(8,'population-accounting','Population accounting & demography','8.3','Track births, deaths, arrivals and departures as counts per interval.',[N('initial','Starting population',1000,0,100000),N('births','Births per interval',100,0,10000),N('deaths','Deaths per interval',50,0,10000),N('immigration','Immigrants per interval',20,0,10000),N('emigration','Emigrants per interval',10,0,10000),N('time','Intervals',20,1,100)],'ΔN = B − D + I − E.','Fixed counts per interval rather than per-capita rates. Negative projected population is truncated at zero; births and departures then no longer follow fixed biological assumptions, so interpretation should stop at extinction. Age structure is not modeled.','How does a fixed birth count differ from a constant per-capita birth rate as population changes?',s=>{let change=s.births-s.deaths+s.immigration-s.emigration,r=Array.from({length:s.time+1},(_,i)=>[i,Math.max(0,s.initial+i*change)]);return output(linearPlot(r,['Population'],'Interval','Individuals'),metrics([[change,'Net change per interval'],[r.at(-1)[1],'Final population']]),[['Interval','Individuals'],...r])});
add(8,'sampling','Population sampling investigation','8.3','Estimate abundance from mark–recapture or quadrat observations.',[S('method','Sampling method','recapture',[['recapture','Mark–recapture'],['quadrat','Quadrat sample']]),N('marked','Initially marked M',50,1,100000),N('capture','Second sample C',40,1,100000),N('recaptured','Marked recaptures R',10,1,100000),N('area','Total habitat area (m²)',1000,1,100000),N('quadrat','Area per quadrat (m²)',1,.01,100,.01),T('counts','Quadrat counts','5, 8, 6, 4, 7','At least 2 nonnegative counts.')],'Lincoln–Petersen: N̂ = MC/R; quadrats: N̂ = mean count × habitat area/quadrat area.','Mark–recapture assumes a closed population, retained marks, thorough mixing and equal capture probability. Quadrat inference assumes representative independent sampling and known habitat area. Outputs are point estimates; no confidence interval is asserted.','Which mark–recapture assumptions would be violated if marked animals became trap-shy?',s=>{let estimate;if(s.method==='recapture'){if(s.recaptured>s.marked||s.recaptured>s.capture)throw Error('Recaptures cannot exceed either marked total or second sample.');estimate=s.marked*s.capture/s.recaptured;}else{let a=s.counts.split(/[ ,;]+/).filter(Boolean).map(Number);if(a.length<2||a.some(x=>!Number.isInteger(x)||x<0))throw Error('Enter at least two nonnegative integer quadrat counts.');if(s.quadrat>s.area)throw Error('Quadrat area cannot exceed habitat area.');estimate=mean(a)*s.area/s.quadrat;}return output(grid([['Abundance estimate',fmt(estimate)],['Method',s.method==='recapture'?'Mark–recapture':'Quadrats']]),metrics([[fmt(estimate),'Estimated individuals']]))});
add(8,'density-disturbance','Density dependence & disturbance','8.4','Change carrying capacity and introduce a discrete population loss.',[N('n0','Initial population',100,1,10000),N('k','Initial carrying capacity',1000,1,10000),N('r','Intrinsic rate (time⁻¹)',.3,.01,1,.01),N('eventtime','Disturbance time',20,0,100),N('loss','Population loss (%)',40,0,100),N('newk','Carrying capacity after event',600,1,10000),N('time','Time span',60,1,100)],'Between events: dN/dt = rN(1−N/K); event removes a chosen population fraction.','Piecewise logistic dynamics with instantaneous disturbance. The event changes population and K independently; the chosen cause is not inferred. Recovery is impossible from exact zero without immigration.','Distinguish the immediate population effect of a disturbance from a lasting change in carrying capacity.',s=>{if(s.eventtime>s.time)throw Error('Event time must be within the plotted span.');let n=s.n0,r=[[0,n]],h=s.time/1000,done=false;for(let i=1;i<=1000;i++){let t=i*h;if(!done&&t>=s.eventtime){n*=1-s.loss/100;done=true;}let k=done?s.newk:s.k;n=n===0?0:k/(1+(k/n-1)*Math.exp(-s.r*h));r.push([t,n]);}return output(linearPlot(r,['Population with disturbance'],'Time (model units)','Individuals'),metrics([[fmt(n),'Final population'],[s.newk,'Post-disturbance K']]),[['Time','Population'],...r])});
add(8,'competition','Competition & coexistence','8.5','Explore two-species competition under logistic resource limitation.',[N('a','Species A initial population',30,.1,1000,.1),N('b','Species B initial population',30,.1,1000,.1),N('ka','Species A carrying capacity',100,1,1000),N('kb','Species B carrying capacity',100,1,1000),N('ab','Effect of B on A, αAB',.5,0,3,.1),N('ba','Effect of A on B, αBA',.5,0,3,.1),N('time','Time span',100,1,200)],'dA/dt = 0.2A[1−(A+αAB B)/KA]; dB/dt = 0.2B[1−(B+αBA A)/KB].','Lotka–Volterra competition model with fixed intrinsic rates 0.2 time⁻¹. Species are homogeneous; resource identity and spatial refuges are not explicit. Outcome depends on coefficients and starting state.','Under what conditions could each species limit itself more strongly than it limits the other?',s=>{let r=integrate([s.a,s.b],([a,b])=>[.2*a*(1-(a+s.ab*b)/s.ka),.2*b*(1-(b+s.ba*a)/s.kb)],s.time);return output(linearPlot(r,['Species A','Species B'],'Time (model units)','Individuals'),metrics([[fmt(r.at(-1)[1]),'Final A'],[fmt(r.at(-1)[2]),'Final B']]),[['Time','A','B'],...r])});
add(8,'foodweb','Food webs & trophic cascades','8.5','Perturb a three-level food chain and trace indirect population effects.',[N('producer','Starting producers',100,.1,1000,.1),N('herbivore','Starting herbivores',15,.1,100,.1),N('predator','Starting predators',5,0,100,.1),S('remove','Perturbation at start','none',[['none','None'],['predator','Remove predators'],['herbivore','Remove herbivores']]),N('time','Time span',60,1,200)],'P grows logistically; herbivory and predation couple adjacent trophic levels.','Illustrative three-level chain: dP=.5P(1−P/300)−.02PH; dH=.005PH−.2H−.03HC; dC=.006HC−.1C. Parameters are examples, not a prediction for a named ecosystem. Removal is complete at t=0; no recolonization.','Why can removing a predator affect producers even when predators do not eat producers?',s=>{let r=integrate([s.producer,s.remove==='herbivore'?0:s.herbivore,s.remove==='predator'?0:s.predator],([p,h,c])=>[.5*p*(1-p/300)-.02*p*h,.005*p*h-.2*h-.03*h*c,.006*h*c-.1*c],s.time);return output(linearPlot(r,['Producers','Herbivores','Predators'],'Time (model units)','Population (model units)'),table(['Link','Effect'],[['Predators → herbivores','Direct consumption'],['Predators → producers','Indirect effect mediated by herbivores']]),[['Time','Producers','Herbivores','Predators'],...r])});
add(8,'interactions','Mutualism & parasitism','8.5','Compare beneficial and harmful effects in a bounded interaction model.',[S('kind','Interaction','mutualism',[['mutualism','Mutualism (+/+)'],['parasitism','Parasitism (−/+)']]),N('strength','Interaction strength',.2,0,.8,.05),N('a','Population A initial',30,1,100),N('b','Population B initial',30,1,100),N('time','Time span',60,1,200)],'Baseline logistic growth plus saturating positive or negative interaction effects.','Illustrative bounded model, not a universal mutualism/parasitism law. Each species has baseline logistic growth .2N(1−N/100); interaction is ±sN(other/(50+other)). A is the host in parasitism.','How could environmental change alter the balance of costs and benefits in an interaction?',s=>{let r=integrate([s.a,s.b],([a,b])=>[.2*a*(1-a/100)+(s.kind==='parasitism'?-1:1)*s.strength*a*b/(50+b),.2*b*(1-b/100)+s.strength*b*a/(50+a)],s.time);return output(linearPlot(r,['Population A','Population B'],'Time (model units)','Population (model units)'),metrics([[s.kind==='parasitism'?'− / +':'+ / +','Signs of direct interaction']]),[['Time','A','B'],...r])});
add(8,'biodiversity','Biodiversity: richness & evenness','8.6','Compare species counts and distinguish richness from abundance balance.',[T('counts','Species abundances','40, 30, 20, 10','One nonnegative integer count per species; zeros excluded from richness.')],'Shannon H = −Σpi ln(pi); Simpson diversity = 1 − Σpi².','Entered sample counts are treated as representative. Shannon and Simpson indices are college extensions and depend on sampling effort. High diversity does not automatically prove ecosystem resilience.','Can two communities have equal richness but different diversity?',s=>{let counts=s.counts.split(/[ ,;\n]+/).filter(Boolean).map(Number);if(!counts.length||counts.length>30||counts.some(x=>!Number.isInteger(x)||x<0)||!counts.some(x=>x>0))throw Error('Enter 1–30 nonnegative species counts with at least one positive count.');let total=counts.reduce((a,b)=>a+b,0),p=counts.filter(x=>x>0).map(x=>x/total),H=-p.reduce((a,b)=>a+b*Math.log(b),0),D=1-p.reduce((a,b)=>a+b*b,0);return output(grid([['Species richness',p.length],['Individuals',total],['Shannon H',fmt(H)],['Simpson 1−Σp²',fmt(D)],['Evenness J',p.length>1?fmt(H/Math.log(p.length)):'Undefined for S=1']]),table(['Species','Count','Relative abundance'],counts.map((n,i)=>[i+1,n,pct(n/total)])),[['Species','Count','Relative abundance'],...counts.map((n,i)=>[i+1,n,n/total])])});
add(8,'disruptions','Nutrient enrichment & oxygen','8.7','Explore nutrient input, algal growth and oxygen demand in a simplified ecosystem.',[N('nutrient','Initial available nutrient',10,0,100),N('input','Nutrient input / time',1,0,5,.1),N('algae','Initial algae biomass',2,.1,100,.1),N('oxygen','Initial dissolved O₂ (mg/L)',8,.1,15,.1),N('time','Time span',60,1,200)],'Nutrient uptake supports growth; biomass turnover increases oxygen demand.','Illustrative three-state eutrophication model with nutrient recycling, biomass loss, and reaeration toward 8 mg/L. Rates are not calibrated to a lake. Oxygen demand is proportional to biomass, with saturation at low oxygen to prevent negative O₂. Does not model temperature, stratification or species-specific tolerance.','How can high daytime photosynthesis coexist with low oxygen during other periods?',s=>{let r=integrate([s.nutrient,s.algae,s.oxygen],([n,a,o])=>{let uptake=.15*a*n/(5+n),loss=.05*a;return[s.input-uptake+.5*loss,uptake-loss,.25*(8-o)-.12*a*o/(1+o)]},s.time);return output(linearPlot(r.map(x=>[x[0],x[2],x[3]]),['Algae (model biomass)','O₂ (mg/L)'],'Time (model units)','Value (series units shown in legend)'),metrics([[fmt(r.at(-1)[3])+' mg/L','Final O₂'],[fmt(r.at(-1)[2]),'Final algal biomass']]),[['Time','Nutrient','Algae','Oxygen mg/L'],...r])});
// SHARED SCIENCE PRACTICES
add(0,'statistics','Graphing & descriptive statistics','All units','Graph entered replicates and keep SD, SE and confidence intervals distinct.',[T('measurements','X, replicate 1, replicate 2, …','0, 1, 1.1, 0.9\n1, 2, 2.2, 1.8\n2, 4, 4.1, 3.9','Each row needs X and at least two replicate values.',true),S('bars','Error bars','sd',[['sd','Sample standard deviation'],['se','Standard error of mean']]),T('xlabel','X-axis label','Treatment (model units)'),T('ylabel','Y-axis label','Measured response (units)')],'SD measures sample spread; SE = SD/√n measures uncertainty of the estimated mean.','Replicates must represent independent experimental units. Error bars are not automatic significance tests. No normality check or confidence interval is inferred. Rows are ordered by X for plotting; choose a numerical X only when appropriate.','Why would technical replicates from one biological sample not justify treating every measurement as an independent organism?',s=>{let r=parseRows(s.measurements,3).map(([x,...a])=>{let m=mean(a),sd=Math.sqrt(a.reduce((v,z)=>v+(z-m)**2,0)/(a.length-1));return[x,m,sd,sd/Math.sqrt(a.length),a.length]}).sort((a,b)=>a[0]-b[0]);let figure=chart([{name:'Mean ± '+s.bars.toUpperCase(),color:colors()[0],values:r.map(x=>[x[0],x[1]]),errors:r.map(x=>x[s.bars==='sd'?2:3]),points:true}],s.xlabel,s.ylabel);return output(figure,table(['X','Mean','SD','SE','n'],r.map(x=>x.map((z,i)=>i===4?z:fmt(z)))),[['X','Mean','SD','SE','n'],...r])});
function chiSquare(obs,ratios){if(obs.length!==ratios.length||obs.length<2)throw Error('Use matching lists with at least two categories.');let total=obs.reduce((a,b)=>a+b,0),sum=ratios.reduce((a,b)=>a+b,0);if(total<=0||sum<=0||obs.some(x=>x<0||!Number.isInteger(x))||ratios.some(x=>x<=0))throw Error('Observed counts must be nonnegative integers; expected ratios must be positive.');const expected=ratios.map(x=>total*x/sum),components=obs.map((x,i)=>(x-expected[i])**2/expected[i]);return{expected,components,value:components.reduce((a,b)=>a+b,0)};}ExtraMath.chiSquare=chiSquare;
add(0,'chi-square','Chi-square goodness of fit','5.3–5.4; science practice 5','Compare observed categorical counts with a specified null-model ratio.',[T('observed','Observed counts','90, 30, 30, 10'),T('ratios','Expected ratio','9, 3, 3, 1'),N('estimated','Parameters estimated from these data',0,0,10),T('null','Null hypothesis','Observed offspring follow a 9:3:3:1 phenotype ratio.')],'χ² = Σ(O−E)²/E; df = categories − 1 − fitted parameters.','Goodness-of-fit test with an externally specified expected ratio unless fitted parameters are entered. Independence and adequate expected counts are required. Uses 0.05 critical values for df 1–10. Fail to reject does not prove the null hypothesis. Small counts trigger a validity warning.','Explain the difference between a large discrepancy and a discrepancy large enough to reject a specified null model.',s=>{let o=s.observed.split(/[ ,;]+/).filter(Boolean).map(Number),rat=s.ratios.split(/[ ,;]+/).filter(Boolean).map(Number);if([...o,...rat].some(x=>!Number.isFinite(x))||o.length>11)throw Error('Enter numeric counts and ratios for 2–11 categories.');let c=chiSquare(o,rat),df=o.length-1-s.estimated,critical=[0,3.841,5.991,7.815,9.488,11.070,12.592,14.067,15.507,16.919,18.307][df];if(!critical)throw Error('Degrees of freedom must be 1–10.');const adequate=c.expected.every(x=>x>=5);return output(grid([['χ²',fmt(c.value)],['df',df],['Critical at α=.05',critical]]),`<p>${esc(s.null)}</p>`+table(['Category','Observed','Expected','Contribution'],o.map((v,i)=>[i+1,v,fmt(c.expected[i]),fmt(c.components[i])]))+`<p class="${adequate?'':'warn'}">${adequate?(c.value>critical?'Reject':'Fail to reject')+' the null at α = 0.05.':'Some expected counts are below 5. Do not use this asymptotic result as a reliable conclusion.'}</p>`,[['Category','Observed','Expected','Contribution'],...o.map((v,i)=>[i+1,v,c.expected[i],c.components[i]])])});
add(0,'experiment','Experimental design & simulated replicates','All units','Compare independent treatments with repeatable measurement variation.',[N('control','Control true mean',10,-100,100),N('treatment','Treatment true mean',12,-100,100),N('sd','Within-group SD',2,.01,20,.01),N('n','Independent replicates per group',10,2,100),N('seed','Random seed',42,1,1000000)],'Observed measurement = group mean + independent normal variation.','Synthetic independent replicates generated with Box–Muller normal sampling. True means and SD are model inputs, not estimated causal facts. No hypothesis test or causal conclusion is automatically asserted. Seed supports reproducibility.','Which controls and randomization would be needed before attributing an observed difference to your treatment?',s=>{let rng=seeded(s.seed),normalRandom=()=>Math.sqrt(-2*Math.log(Math.max(1e-12,rng())))*Math.cos(2*Math.PI*rng()),a=Array.from({length:s.n},()=>s.control+s.sd*normalRandom()),b=Array.from({length:s.n},()=>s.treatment+s.sd*normalRandom()),r=a.map((v,i)=>[i+1,v,b[i]]);return output(chart([{name:'Control synthetic replicates',color:colors()[0],values:r.map(x=>[x[0],x[1]]),points:true},{name:'Treatment synthetic replicates',color:colors()[1],values:r.map(x=>[x[0],x[2]]),points:true}],'Replicate identifier','Measured response (model units)'),metrics([[fmt(mean(a)),'Observed control mean'],[fmt(mean(b)),'Observed treatment mean'],[fmt(mean(b)-mean(a)),'Observed mean difference']]),[['Replicate','Control','Treatment'],...r])});
