add(3,'pigments','Pigment absorption & action spectra','3.4','Compare illustrative pigment absorption and a combined photosynthetic action spectrum.',[N('a','Relative chlorophyll a amount',1,0,2,.1),N('b','Relative chlorophyll b amount',1,0,2,.1),N('carotenoid','Relative carotenoid amount',.5,0,2,.1)],'Different pigments absorb different wavelengths; absorption is not identical to whole-organism photosynthetic action.','Illustrative Gaussian absorption bands centered near common pigment peaks, not measured spectra. Composite action curve is a normalized weighted sum and excludes energy-transfer efficiency and leaf optical effects.','Why can accessory pigments broaden the wavelengths useful for photosynthesis?',s=>{const band=(x,m,w)=>Math.exp(-.5*((x-m)/w)**2),r=Array.from({length:201},(_,i)=>{let x=380+i*2,a=s.a*(band(x,430,18)+.75*band(x,662,16)),b=s.b*(band(x,453,19)+.65*band(x,642,17)),c=s.carotenoid*band(x,475,35);return[x,a,b,c]});return output(linearPlot(r,['Chlorophyll a','Chlorophyll b','Carotenoids'],'Wavelength (nm)','Illustrative relative absorption'),table(['Curve','Interpretation'],[['Pigment curves','Absorption examples; not measured datasets'],['Combined light capture','Accessory pigments broaden potential capture']]),[['Wavelength nm','Chlorophyll a','Chlorophyll b','Carotenoids'],...r])});
add(6,'primers','PCR primer binding & target span','6.8','Locate exact inward-facing primer matches on a defined DNA template.',[T('dna','Template top strand, 5′ → 3′','ATGCCGTAACGTGGGAAATTTCCCGATCGTAC'),T('forward','Forward primer, 5′ → 3′','ATGCCG'),T('reverse','Reverse primer, 5′ → 3′','GTACGA')],'Forward primer matches top-strand sequence; reverse-primer reverse complement matches the opposite target boundary.','Exact-match teaching model without mismatch tolerance, melting temperature, secondary structure or off-target genome search. Primers must be at least 4 bases here; real primers are typically longer. Multiple inward-facing pairs are reported rather than arbitrarily choosing one.','Why must both primers be written 5′→3′ even though they bind different template strands?',s=>{const d=seq(s.dna),f=seq(s.forward),rev=seq(s.reverse),r=revcomp(rev);if(f.length<4||rev.length<4)throw Error('Use primers at least 4 bases long.');let fsites=[],rsites=[];for(let i=0;i<d.length;i++){if(d.startsWith(f,i))fsites.push(i);if(d.startsWith(r,i))rsites.push(i);}let targets=[];for(const a of fsites)for(const b of rsites)if(a+f.length<=b)targets.push([a+1,b+r.length,b+r.length-a,d.slice(a,b+r.length)]);return output(sequenceFigure([['Top-strand template',d],['Forward primer →',f],['Reverse primer, 5′→3′',rev]],`${targets.length} exact inward-facing pair(s)`),targets.length?table(['Start base','End base','Amplicon bp','Target sequence'],targets):'<p class="warn">No exact inward-facing primer pair was found.</p>',[['Start','End','Length bp','Sequence'],...targets])});
add(8,'circadian','Circadian cues & entrainment','8.1','Compare free-running rhythms with an explicitly simplified response to daily cues.',[N('period','Intrinsic period (hours)',24,18,30,.1),N('phase','Starting phase shift (hours)',4,-12,12,.1),S('cue','Environmental cue','daily',[['daily','24-hour cue present'],['none','Constant conditions']]),N('strength','Daily phase-correction fraction',.5,0,1,.1),N('days','Days',5,1,14)],'Internal phase advances with intrinsic period; environmental cues can adjust phase.','Illustrative oscillator with discrete daily phase correction toward the nearest environmental cycle. It does not model a molecular clock or a biological phase-response curve. The waveform is arbitrary relative activity.','Why can an organism retain rhythmic activity without an external day/night cycle?',s=>{let phase=s.phase/24*2*Math.PI,r=[];for(let i=0;i<=s.days*96;i++){let t=i*.25;if(i&&i%96===0&&s.cue==='daily'){let offset=((phase+Math.PI)%(2*Math.PI)+2*Math.PI)%(2*Math.PI)-Math.PI;phase-=s.strength*offset;}r.push([t,.5+.5*Math.sin(phase),.5+.5*Math.sin(2*Math.PI*t/24)]);phase+=2*Math.PI*.25/s.period;}return output(linearPlot(r,['Internal relative activity','24-hour environment'],'Time (hours)','Relative signal'),table(['Intrinsic period','Cue condition'],[[s.period+' hours',s.cue]]),[['Hours','Internal signal','Environmental signal'],...r])});
add(8,'invasion','Invasion & resource competition','8.7','Introduce a competitor into an established resident population.',[N('resident','Starting resident population',90,1,1000),N('introduced','Introduced population',5,.1,100,.1),N('impact','Invader effect on resident',1.5,0,3,.1),N('resistance','Resident effect on invader',.4,0,3,.1),N('time','Time span',80,1,200)],'Resident and introduced species interact through logistic competition.','Both species have K=100; resident r=.2 and introduced r=.25 time⁻¹. Coefficients are hypothetical; introduced species are not universally competitively superior. The model excludes enemies, facilitation and spatial heterogeneity.','Which observations would distinguish competition from a different explanation for resident decline?',s=>{let r=integrate([s.resident,s.introduced],([a,b])=>[.2*a*(1-(a+s.impact*b)/100),.25*b*(1-(b+s.resistance*a)/100)],s.time);return output(linearPlot(r,['Resident','Introduced species'],'Time (model units)','Individuals'),metrics([[fmt(r.at(-1)[1]),'Final resident population'],[fmt(r.at(-1)[2]),'Final introduced population']]),[['Time','Resident','Introduced'],...r])});
add(8,'habitat','Habitat loss & patch connectivity','8.7','Explore colonization and extinction in a patch-occupancy model.',[N('occupied','Initially occupied patches (fraction)',.5,.001,1,.001),N('colonization','Colonization coefficient (time⁻¹)',.4,.001,2,.001),N('extinction','Local extinction coefficient (time⁻¹)',.1,0,2,.001),N('available','Habitat remaining (fraction)',1,.05,1,.05),N('time','Time span',50,1,200)],'dp/dt = cp(h−p) − ep, with p as occupied fraction of original habitat and h as remaining habitat.','Levins-style college extension with homogeneous patches and mass-action colonization. Initial occupancy cannot exceed remaining habitat. Habitat loss is represented by h; connectivity is represented by c. Occupancy is not population abundance.','Why could restoring connectivity and restoring habitat area have different effects?',s=>{if(s.occupied>s.available)throw Error('Occupied fraction cannot exceed remaining habitat fraction.');let r=integrate([s.occupied],([p])=>[s.colonization*p*(s.available-p)-s.extinction*p],s.time),equilibrium=Math.max(0,s.available-s.extinction/s.colonization);return output(linearPlot(r,['Occupied fraction of original habitat'],'Time (model units)','Occupied fraction'),metrics([[fmt(equilibrium),'Positive equilibrium if > 0'],[fmt(r.at(-1)[1]),'Final occupied fraction']]),[['Time','Occupied fraction'],...r])});
add(8,'resilience','Functional diversity & response','8.6–8.7','Compare aggregate function when groups differ in disturbance sensitivity.',[N('groups','Functional response groups',4,1,8),N('disturbance','Disturbance severity',.5,0,1,.05),S('variation','Sensitivity pattern','diverse',[['diverse','Groups differ in sensitivity'],['same','All groups equally sensitive']])],'Aggregate remaining function = sum of group contributions after disturbance.','Illustrative functional-response accounting: equal initial contributions; diverse sensitivities range from 0.2 to 1, while identical sensitivity is 0.6. Remaining contribution = max(0,1−severity×sensitivity). This selected scenario does not establish a universal diversity–resilience law or simulate recovery.','What additional evidence is needed before using species richness to predict ecosystem stability?',s=>{let sens=Array.from({length:s.groups},(_,i)=>s.variation==='same'?.6:s.groups===1?.6:.2+.8*i/(s.groups-1)),remain=sens.map(x=>Math.max(0,1-s.disturbance*x));return output(grid(remain.map((v,i)=>['Response group '+(i+1),pct(v)])),metrics([[pct(mean(remain)),'Remaining aggregate function / initial']])+table(['Group','Sensitivity','Remaining contribution'],sens.map((v,i)=>[i+1,fmt(v),fmt(remain[i])])),[['Group','Sensitivity','Remaining fraction'],...sens.map((v,i)=>[i+1,v,remain[i]])])});
